INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q939211', 'Battle of Brávellier', 'The Battle of Brávellir or the Battle of Bråvalla was a legendary battle, said to have taken place c. 770, that is described in the sagas as taking place on the Brávellir between Sigurd Hring, king of Sweden and the Geats of Västergötland, and his uncle Harald Wartooth, king of Denmark and the Geats of Östergötland.', 800, NULL, NULL, NULL, NULL, NULL, 'century', '8th century', 57, 'https://en.wikipedia.org/wiki/Battle_of_Br%C3%A1vellir'),
  ('Q2664985', 'Battle of Fýrisvellir', 'The Battle of Fýrisvellir was fought in the 980s on the plain called Fýrisvellir, where modern Uppsala is situated, between King Eric the Victorious and an invading force. According to Norse sagas, this force was led by his nephew Styrbjörn the Strong.', 980, NULL, NULL, NULL, NULL, NULL, 'decade', '980s', 48, 'https://en.wikipedia.org/wiki/Battle_of_F%C3%BDrisvellir'),
  ('Q499768', 'Battle of Helgeå', 'The Battle of Helgeå (Norwegian: Slaget ved Helgeå, Swedish: Slaget vid Helgeå), or Battle of the Holy River, was a naval engagement that took place in 1026 between joint Danish and English forces and a combined Norwegian and Swedish force, at the estuary of a river called Helge (Holy River) in Denmark or Sweden. King Olaf II of Norway and King Anund Jacob of Sweden took advantage of the commitment of Danish King Cnut in England and began to launch attacks on the Danish in the Baltic Sea.', 1026, NULL, NULL, NULL, NULL, NULL, 'year', '1026', 50, 'https://en.wikipedia.org/wiki/Battle_of_Helge%C3%A5'),
  ('Q3353388', 'Battle of Niså', 'The Battle of Niså (Slaget ved Niså) was a naval battle fought on 9 August 1062 between the forces of Norwegian king Harald Hardrada and king Sweyn II of Denmark. Harald had claimed the Danish throne since 1047, and had launched raids into Denmark ever since.', 1062, 8, 9, NULL, NULL, NULL, 'day', '9 August 1062', 47, 'https://en.wikipedia.org/wiki/Battle_of_Nis%C3%A5'),
  ('Q3353382', 'Battle of Fotevik', 'Battle of Fotevik (Danish: Slaget ved Fodevig) was fought between forces of King Niels of Denmark and his son Magnus Nielsen, against those of Erik Emune on 4 June 1134 at the bay of Fotevik in Skåne. At his death, King Eric I of Denmark had two known sons who were candidates for succession to the throne, Canute Lavard and Erik Emune.', 1134, 6, 4, NULL, NULL, NULL, 'day', '4 June 1134', 43, 'https://en.wikipedia.org/wiki/Battle_of_Fotevik'),
  ('Q1778251', 'Battle of Älgarås', 'The Battle of Älgarås took place at the royal estate of Älgarås in northernmost Västergötland in November 1205 between the House of Sverker and the House of Eric who were fighting for the Swedish crown. The four sons of the former king Canute I fell out with King Sverker II in about 1204 and sought support among the Birkebeiner party in Norway.', 1205, 11, 14, NULL, NULL, NULL, 'day', '14 November 1205', 47, 'https://en.wikipedia.org/wiki/Battle_of_%C3%84lgar%C3%A5s'),
  ('Q367025', 'Battle of Lena', 'The Battle of Lena occurred on 31 January 1208 and probably took place near Kungslena, in the Tidaholm Municipality in Västergötland, Sweden. It was an important battle between the Danish-backed King Sverker II of Sweden and Prince Eric.', 1208, 1, 31, NULL, NULL, NULL, 'day', '31 January 1208', 50, 'https://en.wikipedia.org/wiki/Battle_of_Lena'),
  ('Q1778630', 'Battle of Gestilren', 'The Battle of Gestilren took place on July 17, 1210. The battle was fought between the exiled King of Sweden Sverker and the ruling King Eric X. Sverker had been beaten in the previous Battle of Lena, but returned with new forces.', 1210, 7, 17, NULL, NULL, NULL, 'day', '17 July 1210', 47, 'https://en.wikipedia.org/wiki/Battle_of_Gestilren'),
  ('Q1792257', 'Battle of Sparrsätra', 'The Battle of Sparrsätra was fought in 1247 between the forces of King Eric XI of Sweden and rebels led by Holmger Knutsson near Enköping in Sweden. It occurred during a poorly documented period in Swedish history; as a result, many details are uncertain and conjectural.', 1247, NULL, NULL, NULL, NULL, NULL, 'year', '1247', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sparrs%C3%A4tra'),
  ('Q1794521', 'Battle of Hova', 'The Battle of Hova (Swedish: Slaget vid Hova) was fought in Hova, Sweden on 14 June 1275 between peasants commanded by King Valdemar of Sweden and Danish cavalry commanded by Duke Magnus and his brother Erik. The result was that Valdemar had to flee to Norway and Magnus became king of Sweden.', 1275, 6, 14, NULL, NULL, NULL, 'day', '14 June 1275', 37, 'https://en.wikipedia.org/wiki/Battle_of_Hova'),
  ('Q11956522', '6000-Mark War', 'The 6000-mark war (Swedish: 6000-markskriget, Danish: 6000-marks-krigen) was a war between Denmark and Sweden which took place from 1276 to 1278. It started because of a disagreement over an agreed sum of 6,000 silver marks for Danish assistance to Magnus Birgersson in the battle against Valdemar Birgersson in 1275.', 1276, NULL, NULL, 1278, NULL, NULL, 'year', '1276–1278', 37, 'https://en.wikipedia.org/wiki/6000-mark_war'),
  ('Q624937', 'Battle of Visby', 'The Battle of Visby was fought in 1361 near the town of Visby on the island of Gotland, Sweden, between the forces of the Danish king and the Gutnish country yeomen. The Danish force was victorious.', 1361, 7, 27, NULL, NULL, NULL, 'day', '27 July 1361', 51, 'https://en.wikipedia.org/wiki/Battle_of_Visby'),
  ('Q3503678', 'Battle of Helsingborg', 'The Battle of Helsingborg was fought on 8 July 1362 between the Danish and Hanseatic fleets during the Danish-Hanseatic War (1361–1370).', 1362, 7, 8, NULL, NULL, NULL, 'day', '8 July 1362', 47, 'https://en.wikipedia.org/wiki/Battle_of_Helsingborg_(1362)'),
  ('Q1794532', 'Battle of Åsle', 'The Battle of Åsle was the decisive battle between King Albert of Mecklenburg''s and Queen Margaret Valdemarsdotter''s forces in 1389. The battle took place at Åsle church village about one Swedish mile (10 km) east of Falköping.', 1389, 2, 24, NULL, NULL, NULL, 'day', '24 February 1389', 39, 'https://en.wikipedia.org/wiki/Battle_of_%C3%85sle'),
  ('Q1277593', 'Dano-Swedish War', 'The Dano-Swedish War was the first conflict between Denmark and Sweden. The Danes invaded Sweden by sea, but were defeated early at the Battle of Brunkeberg, in which King Christian I of Denmark was wounded by a cannonball.', 1470, NULL, NULL, 1471, NULL, NULL, 'year', '1470–1471', 43, 'https://en.wikipedia.org/wiki/Dano-Swedish_War_(1470%E2%80%931471)'),
  ('Q1638031', 'Battle of Brunkeberg', 'The Battle of Brunkeberg was fought on 10 October 1471 between the Swedish regent Sten Sture the Elder and forces led by Danish king Christian I. Sture won a decisive victory, weakening the Kalmar Union considerably and becoming the effective ruler of Sweden as Lord Regent for most of his remaining life.', 1471, 10, 10, NULL, NULL, NULL, 'day', '10 October 1471', 52, 'https://en.wikipedia.org/wiki/Battle_of_Brunkeberg'),
  ('Q2371630', 'Battle of Rotebro', 'The Battle of Rotebro was fought on 28 September 1497 between the armies of John, King of Denmark and Sten Sture the Elder, the deposed regent of Sweden. Sten Sture had fallen out of favor with the nobility and was deposed on March 1497 of his post as Regent of Sweden.', 1497, 9, 28, NULL, NULL, NULL, 'day', '28 September 1497', 37, 'https://en.wikipedia.org/wiki/Battle_of_Rotebro'),
  ('Q846876', 'Stockholm Bloodbath', 'The Stockholm Bloodbath (Swedish: Stockholms blodbad) was a trial that led to a series of executions in Stockholm between 7 and 9 November 1520. The event is also known as the Stockholm massacre.', 1520, NULL, NULL, 1520, 11, 9, 'year', '1520', 72, 'https://en.wikipedia.org/wiki/Stockholm_Bloodbath'),
  ('Q1606958', 'Battle of Bogesund', 'The Battle of Bogesund was an important conflict in the campaign of Christian II to gain power over Sweden. In 1520, Christian''s army of mercenaries had landed in Sweden, seeking to consolidate Christian''s powers over Sweden within the Kalmar Union and to unseat the rebellious Swedish riksföreståndare Sten Sture the Younger.', 1520, 1, 19, NULL, NULL, NULL, 'day', '19 January 1520', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bogesund'),
  ('Q2371616', 'Conquest of Stockholm', 'The Conquest of Stockholm (Swedish: Erövringen av Stockholm) was a battle in the Swedish War of Liberation that took place in Stockholm, Sweden on 17 June 1523. The Swedish forces had for a long time laid siege to Stockholm, which was the last Danish stronghold in Sweden.', 1523, 6, 17, NULL, NULL, NULL, 'day', '17 June 1523', 39, 'https://en.wikipedia.org/wiki/Conquest_of_Stockholm'),
  ('Q2890945', 'Battle of Axtorna', 'The Battle of Axtorna or simply Axtorna, was fought between the Kingdom of Sweden and Denmark–Norway 20 October 1565 at Axtorna, a small village in what is today Falkenberg Municipality, Halland County in south-western Sweden.', 1565, 10, 20, NULL, NULL, NULL, 'day', '20 October 1565', 41, 'https://en.wikipedia.org/wiki/Battle_of_Axtorna'),
  ('Q371409', 'Battle of Stångebro', 'The Battle of Stångebro, or the Battle of Linköping, took place at Linköping, Sweden, on 25 September 1598 (O.S.) and effectively ended the personal union between Sweden and the Polish–Lithuanian Commonwealth, that had formed in 1592. In the battle, an army of somewhere between 8,000 and 12,000 commanded by Duke Charles defeated a mixed force of roughly 5,000 and 8,000 men consisting of an invading army of mercenaries in the king''s employ and diverse but poorly co-ordinated supporting Swedish noblemen''s forces commanded by King of both Sweden and the Polish–Lithuanian Commonwealth,…', 1598, 9, 25, NULL, NULL, NULL, 'day', '25 September 1598', 50, 'https://en.wikipedia.org/wiki/Battle_of_St%C3%A5ngebro'),
  ('Q546505', 'Battle of Stegeborg', 'The Battle of Stegeborg took place in a meadow near Stegeborg Castle, Sweden on September 18 (N.S.), or September 8 (O.S.), 1598. It is part of the so-called War against Sigismund, in turn part of the Polish–Swedish Wars.', 1598, 9, 8, NULL, NULL, NULL, 'day', '8 September 1598', 37, 'https://en.wikipedia.org/wiki/Battle_of_Stegeborg'),
  ('Q2138526', 'Treaty of Knäred', 'The Treaty of Knäred (Danish: Freden i Knærød, Swedish: Freden i Knäred) was signed on 21 January 1613 and ended the Kalmar War (1611–1613) between Denmark-Norway and Sweden. The peace negotiations came about under an English initiative.', 1613, 1, 21, NULL, NULL, NULL, 'day', '21 January 1613', 53, 'https://en.wikipedia.org/wiki/Treaty_of_Kn%C3%A4red'),
  ('Q2237118', 'Battle of Triebl', 'The Battle of Triebl or Battle of Třebel took place on 22 August 1647 during the Thirty Years'' War. Imperial cavalry under Raimondo Montecuccoli and Johann von Werth launched a surprise attack on the Swedish camp of Carl Gustaf Wrangel and inflicted 380, or more than 1,300, losses on them in exchange for 200–300 casualties.', 1647, 8, 18, 1647, 9, 5, 'day', '18 August 1647 – 5 September 1647', 39, 'https://en.wikipedia.org/wiki/Battle_of_Triebl'),
  ('Q1536103', 'Battle of Lund', 'The Battle of Lund, part of the Scanian War, was fought on 4 December 1676, in an area north of the city of Lund in Scania in southern Sweden, between the invading Danish army and the army of Charles XI of Sweden. The Danish had an army of about 13,000 under the personal command of 30-year-old King Christian V of Denmark, aided by General Carl von Arensdorff.', 1676, 12, 4, NULL, NULL, NULL, 'day', '4 December 1676', 57, 'https://en.wikipedia.org/wiki/Battle_of_Lund'),
  ('Q2888779', 'Battle of Halmstad', 'The Battle of Halmstad, also known as the Battle at Fyllebro, was fought on 17 August 1676, at Fyllebro, approximately 4 km (2.5 mi) southeast of the town of Halmstad in the province of Halland in southwest Sweden. It was the last battle fought in Halland between Denmark and Sweden.', 1676, 8, 17, NULL, NULL, NULL, 'day', '17 August 1676', 43, 'https://en.wikipedia.org/wiki/Battle_of_Halmstad'),
  ('Q2888037', 'Battle of Uddevalla', 'The Battle of Uddevalla took place at Uddevalla on August 28, 1677 as part of the Scanian War.', 1677, 8, 28, NULL, NULL, NULL, 'day', '28 August 1677', 37, 'https://en.wikipedia.org/wiki/Battle_of_Uddevalla'),
  ('Q2889107', 'Battle of Landskrona', 'The Battle of Landskrona was a battle in the Scanian War, fought between Denmark and Sweden. It occurred on Ylleshed moor, outside the town of Landskrona, in the province of Scania in what is now southern Sweden on 14 July 1677.', 1677, 7, 14, NULL, NULL, NULL, 'day', '14 July 1677', 45, 'https://en.wikipedia.org/wiki/Battle_of_Landskrona'),
  ('Q4582269', 'Siege of Malmö', 'The siege of Malmö (Swedish: Belägringen av Malmö) was an unsuccessful Danish siege on the Swedish-held city of Malmö, fought between June 11 and July 5, 1677. Fought towards the end of the Scanian War, the siege was one in a string of Danish losses that saw Swedish forces under King Charles XI of Sweden establish control over the southern region of Sweden.', 1677, 6, 11, 1677, 7, 5, 'day', '11 June 1677 – 5 July 1677', 43, 'https://en.wikipedia.org/wiki/Siege_of_Malm%C3%B6'),
  ('Q15963786', 'Battle of Lemberg', 'The Storming of Lemberg or Lviv on 6 September 1704 (N.S.) was a successful Swedish assault on the city of Lemberg (Lviv), in the Polish–Lithuanian Commonwealth, during the Great Northern War.', 1704, 9, 6, NULL, NULL, NULL, 'day', '6 September 1704', 39, 'https://en.wikipedia.org/wiki/Storming_of_Lemberg'),
  ('Q705409', 'Battle of Helsingborg', 'The Battle of Helsingborg was the last major engagement of the Great Northern War to take place on Swedish soil. It resulted in a decisive victory of a Swedish force of 14,000 men under the command of Magnus Stenbock against a Danish force of equal strength under the command of Jørgen Rantzau, ensuring that Denmark''s final effort to regain the Scanian territories that it had lost to Sweden in 1658 failed.', 1710, 3, 10, NULL, NULL, NULL, 'day', '10 March 1710', 51, 'https://en.wikipedia.org/wiki/Battle_of_Helsingborg'),
  ('Q5599700', 'Great Northern War plague outbreak', 'During the Great Northern War (1700–1721), many towns and areas around the Baltic Sea and East-Central Europe had a severe outbreak of the plague with a peak from 1708 to 1712. This epidemic was probably part of a pandemic affecting an area from Central Asia to the Mediterranean.', 1710, 6, NULL, 1711, 2, NULL, 'month', 'June 1710 – February 1711', 56, 'https://en.wikipedia.org/wiki/Great_Northern_War_plague_outbreak'),
  ('Q2578587', 'Greater Wrath', 'The Great Wrath was the period of Russian military occupation in Finland during the final phase of the Great Northern War. At the time, Finland was part of the Swedish Empire.', 1713, NULL, NULL, 1721, NULL, NULL, 'year', '1713–1721', 55, 'https://en.wikipedia.org/wiki/Great_Wrath'),
  ('Q694122', 'Battle of Napue', 'The Battle of Napue, the Battle of Isokyrö (Storkyro), or the Battle of Lappola was fought on 2 March [O.S. 19 February] 1714 at the villages of Napue and Laurola, located in the Isokyrö parish of the Swedish Empire (modern-day Finland). The battle took place between the Swedish Empire and the Tsardom of Russia and was the final land battle of the Finnish campaign in the Great Northern War.', 1714, 3, 2, NULL, NULL, NULL, 'day', '2 March 1714', 50, 'https://en.wikipedia.org/wiki/Battle_of_Napue'),
  ('Q1844815', 'Battle of Dynekilen', 'The naval Battle of Dynekilen (Danish: Slaget ved Dynekilen) took place on 8 July 1716 during the Great Northern War between a Dano-Norwegian fleet under Peter Tordenskjold and a Swedish fleet under Olof Strömstierna. The battle resulted in a Dano-Norwegian victory.', 1716, 7, 8, NULL, NULL, NULL, 'day', '8 July 1716', 48, 'https://en.wikipedia.org/wiki/Battle_of_Dynekilen'),
  ('Q3500708', 'Battle of Stäket', 'The Battle of Stäket was a minor battle on 24 August 1719 (N.S.) during the Great Northern War. A probing Russian force, circumventing Vaxholm Castle, attempted to pass through Baggensstäket, a very narrow passage in the Stockholm archipelago.', 1719, 8, 13, NULL, NULL, NULL, 'day', '13 August 1719', 43, 'https://en.wikipedia.org/wiki/Battle_of_St%C3%A4ket'),
  ('Q3791537', 'Attack on Marstrand', 'The attack on Marstrand was a successful Dano-Norwegian siege of the Swedish town of Marstrand and Carlsten fortress which took place between 21–27 July 1719 (N.S.) during the end of the Great Northern War. After a Dano-Norwegian assault on northern Bohuslän, ships under the command of Peter Tordenskjold attacked the Swedes at Marstrand harbor and the immobile ships of the Swedish Gothenburg Fleet.', 1719, NULL, NULL, 1719, 7, 16, 'year', '1719', 37, 'https://en.wikipedia.org/wiki/Attack_on_Marstrand'),
  ('Q153286', 'Treaty of Nystad', 'The Treaty of Nystad, or the Treaty of Uusikaupunki, was the last peace treaty of the Great Northern War of 1700–1721. It was concluded between the Tsardom of Russia and the Swedish Empire on 10 September [O.S. 30 August] 1721 in the then Swedish town of Nystad (Uusikaupunki, in the south-west of present-day Finland).', 1721, 8, 30, NULL, NULL, NULL, 'day', '30 August 1721', 74, 'https://en.wikipedia.org/wiki/Treaty_of_Nystad'),
  ('Q48551', 'Lapp Codicil of 1751', 'Lapp Codicil of 1751 is an addendum to the Strömstad Treaty of 1751 that defined the Norwegian-Swedish border. It consists of 30 sections.', 1751, 10, 2, NULL, NULL, NULL, 'day', '2 October 1751', 43, 'https://en.wikipedia.org/wiki/Lapp_Codicil_of_1751'),
  ('Q10511142', 'Revolution of 1772', 'The Revolution of 1772, also known as The Bloodless Revolution (Swedish: Revolutionen) or the Coup of Gustav III (Gustav III:s statskupp or older Gustav III:s statsvälvning), was a Swedish coup d''état performed by King Gustav III on 19 August 1772 to introduce a division of power between the King and the Riksdag of the Estates, resulting in the end of the Age of Liberty and the introduction of the Swedish Constitution of 1772, which would strengthen the power of the monarch and the start the absolutist period known as the Gustavian era.', 1772, 8, 19, NULL, NULL, NULL, 'day', '19 August 1772', 50, 'https://en.wikipedia.org/wiki/Revolution_of_1772'),
  ('Q1130792', 'Treaty of Fredrikshamn', 'The Treaty of Fredrikshamn, or the Treaty of Hamina, was a peace treaty concluded between Sweden and Imperial Russia on 17 September 1809. The treaty concluded the Finnish War and was signed in the Finnish town of Fredrikshamn (Hamina).', 1809, 9, 5, NULL, NULL, NULL, 'day', '5 September 1809', 67, 'https://en.wikipedia.org/wiki/Treaty_of_Fredrikshamn'),
  ('Q2334896', '1809 Swedish coup d''état', 'The Coup of 1809 (Swedish: Statskuppen 1809), also referred to as the Revolution of 1809 (Swedish: Revolutionen 1809), was a Swedish coup d''état on 13 March of that year by a group of noblemen led by Georg Adlersparre, with support from the Western Army. The coup resulted in the deposition of King Gustav IV Adolf and the introduction of a new Instrument of Government.', 1809, 3, 7, 1809, 5, 10, 'day', '7 March 1809 – 10 May 1809', 48, 'https://en.wikipedia.org/wiki/Coup_of_1809'),
  ('Q1558846', 'Finnish famine of 1866–1868', 'The Finnish famine of 1866–1868 was the last famine in Finland, and (along with the subsequent Swedish famine of 1867–1869) the last major famine in Northern Europe. In Finland, the famine is known as "the great hunger years", or suuret nälkävuodet.', 1867, NULL, NULL, 1869, NULL, NULL, 'year', '1867–1869', 57, 'https://en.wikipedia.org/wiki/Finnish_famine_of_1866%E2%80%931868'),
  ('Q4060498', 'Invasion of Åland', 'The Invasion of Åland was a 1918 military campaign of World War I in Åland, Finland. The islands, still hosting Soviet Russian troops, were first invaded by Sweden in late February and then by the German Empire in early March.', 1918, 2, 15, 1918, 9, NULL, 'day', '15 February 1918 – September 1918', 50, 'https://en.wikipedia.org/wiki/Invasion_of_%C3%85land'),
  ('Q1796006', '1922 Swedish prohibition referendum', 'A non-binding referendum on prohibition of liquor was held in Sweden on 27 August 1922. The proposal to prohibit the sale of alcohol failed, with 51% voting against the change on a turnout of 55.1%.', 1922, 8, 27, NULL, NULL, NULL, 'day', '27 August 1922', 41, 'https://en.wikipedia.org/wiki/1922_Swedish_prohibition_referendum'),
  ('Q4569320', 'Catalina affair', 'The Catalina affair (Swedish: Catalinaaffären) was a military confrontation and Cold War-era diplomatic crisis in June 1952, in which Soviet Air Force fighter jets shot down two Swedish aircraft over international waters in the Baltic Sea. The first aircraft to be shot down was an unarmed Swedish Air Force Tp 79, a derivative of the Douglas DC-3, carrying out radio and radar signals intelligence-gathering for the National Defence Radio Establishment (Försvarets radioanstalt, FRA).', 1952, 6, 16, NULL, NULL, NULL, 'day', '16 June 1952', 51, 'https://en.wikipedia.org/wiki/Catalina_affair'),
  ('Q376921', 'Dagen H', 'Dagen H (H-day), today usually called "Högertrafikomläggningen" (lit. ''the right-hand traffic reorganisation''), was on 3 September 1967, the day on which Sweden switched from driving on the left-hand side of the road to the right. The "H" stands for "Högertrafik", the Swedish word for right-hand traffic.', 1967, 9, 3, NULL, NULL, NULL, 'day', '3 September 1967', 69, 'https://en.wikipedia.org/wiki/Dagen_H'),
  ('Q6554197', 'Linjeflyg Flight 618', 'Linjeflyg Flight 618 was a crash of a Vickers 838 Viscount during approach to Stockholm Bromma Airport at 09:05 on 15 January 1977. All twenty-two people on board the aircraft perished when it hit ground at Kälvesta in Stockholm, Sweden.', 1977, 1, 15, NULL, NULL, NULL, 'day', '15 January 1977', 47, 'https://en.wikipedia.org/wiki/Linjeflyg_Flight_618'),
  ('Q3284177', 'assassination of Olof Palme', 'On 28 February 1986, at 23:21 CET (22:21 UTC), Olof Palme, Prime Minister of Sweden, was fatally wounded by a single gunshot while walking home from a cinema with his wife Lisbeth Palme on the central Stockholm street Sveavägen. Lisbeth Palme was slightly wounded by a second shot.', 1986, 2, 28, NULL, NULL, NULL, 'day', '28 February 1986', 61, 'https://en.wikipedia.org/wiki/Assassination_of_Olof_Palme'),
  ('Q1529863', 'Scandinavian Airlines System Flight 751', 'Scandinavian Airlines System Flight 751 was a regularly scheduled Scandinavian Airlines passenger flight from Stockholm, Sweden, to Warsaw, Poland, via Copenhagen, Denmark. On 27 December 1991, a McDonnell Douglas MD-81 operating the flight, registration OY-KHO, piloted by Danish Captain Stefan G. Rasmussen (44) and Swedish first officer Ulf Cedermark (34), both experienced pilots with 8,000 and 3,000 flight hours, respectively, was forced to make an emergency landing in a field near Gottröra, Sweden.', 1991, 12, 27, NULL, NULL, NULL, 'day', '27 December 1991', 59, 'https://en.wikipedia.org/wiki/Scandinavian_Airlines_System_Flight_751'),
  ('Q5587844', 'Gothenburg discothèque fire', 'The Gothenburg discothèque fire was caused by an arson attack on 29 October 1998, which occurred on premises located on Hisingen island in Gothenburg, Sweden. The premises, which belonged to an organization catering to the Macedonian community in Gothenburg, had been rented for the night by secondary school students for the purpose of hosting a discothèque.', 1998, 10, 29, 1998, 10, 30, 'day', '29 October 1998 – 30 October 1998', 43, 'https://en.wikipedia.org/wiki/1998_Gothenburg_discotheque_fire'),
  ('Q4352712', '2003 Swedish euro referendum', 'A non-binding referendum on introduction of the euro was held in Sweden on 14 September 2003. The majority voted not to adopt the euro, and thus Sweden decided in 2003 not to adopt the euro for the time being.', 2003, 9, 14, NULL, NULL, NULL, 'day', '14 September 2003', 48, 'https://en.wikipedia.org/wiki/2003_Swedish_euro_referendum'),
  ('Q4129687', '2008 Skåne County earthquake', 'The 2008 Scania earthquake occurred at 06.20am CET (05.20 UTC) on 16 December and affected the southern part of Sweden and eastern parts of Denmark. The epicenter was 5 km southwest of Sjöbo and 60 km east of Malmö in Scania.', 2008, 12, 16, NULL, NULL, NULL, 'day', '16 December 2008', 43, 'https://en.wikipedia.org/wiki/2008_Scania_earthquake'),
  ('Q2010333', '2012 Norwegian Air Force C-130 crash', 'On 15 March 2012, a C-130J Super Hercules military transport aircraft of the Royal Norwegian Air Force (Norwegian: Luftforsvaret) crashed into the western face of Mount Kebnekaise near Kiruna, Sweden. All five people on board were killed.', 2012, 3, 15, NULL, NULL, NULL, 'day', '15 March 2012', 50, 'https://en.wikipedia.org/wiki/2012_Norwegian_Air_Force_C-130_crash'),
  ('Q13368710', '2013 Stockholm riots', 'On 19 May 2013, violent disturbances broke out in Husby, a suburb dominated by immigrants and second-generation immigrant residents, including a substantial number from Somalia, Eritrea, Afghanistan and Iraq, in northern Stockholm, Sweden. The riots were reportedly in response to the shooting to death by police of an elderly man, reportedly a Portuguese expatriate, armed with a puukko knife, after entering his apartment and then allegedly trying to cover up the man''s death.', 2013, NULL, NULL, 2013, 5, 28, 'year', '2013', 55, 'https://en.wikipedia.org/wiki/May_2013_Stockholm_riots'),
  ('Q21995232', 'West Air Sweden Flight 294', 'West Air Sweden Flight 294 was a cargo flight of a Bombardier CRJ200 from Oslo to Tromsø, Norway, that crashed on 8 January 2016. A malfunction in one of the inertial reference units had produced erroneous attitude indications on one of the instrument displays.', 2016, 1, 8, NULL, NULL, NULL, 'day', '8 January 2016', 57, 'https://en.wikipedia.org/wiki/West_Air_Sweden_Flight_294'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
